from datetime import datetime

def calculate_age(born):
    today = datetime.today()
    return today.year - born.year - ((today.month, today.day) < (born.month, born.day))

def compare_ages(item1, item2):
    born1 = datetime.strptime(item1['dob'], '%Y-%m-%d')
    born2 = datetime.strptime(item2['dob'], '%Y-%m-%d')
    age1 = calculate_age(born1)
    age2 = calculate_age(born2)
    if age1 > age2:
        return '1'
    else:
        return '0'

